#pragma once

#include <vector>
#include <sstream>
#include <chrono>
#include <fstream>
#include <iomanip>
#include "sim/keepaway_env.hpp"

using namespace keepaway;

struct Episode
{
    double seconds;
    EndReason reason;
};

struct Row
{
    std::string name;
    std::vector<Episode> eps;
};

inline const char *reason_name(EndReason r)
{
    switch (r)
    {
    case EndReason::Steal:
        return "steal";
    case EndReason::OutOfBounds:
        return "out";
    case EndReason::Truncated:
        return "truncated";
    default:
        return "none";
    }
}

inline void print_row(const std::string &name, const std::vector<Episode> &eps)
{
    std::vector<double> s;
    int steals = 0, outs = 0, trunc = 0;
    for (const Episode &e : eps)
    {
        s.push_back(e.seconds);
        if (e.reason == EndReason::Steal)
            ++steals;
        if (e.reason == EndReason::OutOfBounds)
            ++outs;
        if (e.reason == EndReason::Truncated)
            ++trunc;
    }
    double mean = 0.0;
    for (double v : s)
        mean += v;
    mean /= s.size();
    double var = 0.0;
    for (double v : s)
        var += (v - mean) * (v - mean);
    double sd = s.size() > 1 ? std::sqrt(var / (s.size() - 1)) : 0.0;
    std::sort(s.begin(), s.end());
    double median = s[s.size() / 2];
    std::printf("%-18s mean %7.2f s  sd %6.2f  median %6.2f   steal %4d  out %4d  truncated %d\n",
                name.c_str(), mean, sd, median, steals, outs, trunc);
}

// [Claude] Average possession time (seconds) of every block of `block` episodes, on one line.
// The last block can be shorter if the episode count is not a multiple of `block`.
inline void print_block_averages(const std::vector<Episode> &eps, size_t block = 1000)
{
    std::printf("  per %zu episodes:", block);
    for (size_t start = 0; start < eps.size(); start += block)
    {
        size_t end = (start + block < eps.size()) ? start + block : eps.size();
        double sum = 0.0;
        for (size_t i = start; i < end; ++i)
            sum += eps[i].seconds;
        std::printf(" %.1f", sum / (end - start));
    }
    std::printf("\n");
}

inline void save_csv(const std::vector<Row> &rows, const std::string &baseName)
{
    auto now = std::chrono::system_clock::now();
    std::time_t now_c = std::chrono::system_clock::to_time_t(now);

    std::stringstream ss;
    ss << baseName << "_"
       << std::put_time(std::localtime(&now_c), "%Y-%m-%d_%H-%M-%S")
       << ".csv";

    std::ofstream csv(ss.str());
    csv << "policy,episode,seconds,end_reason\n";
    for (const Row &r : rows)
        for (size_t e = 0; e < r.eps.size(); ++e)
            csv << r.name << ',' << e << ',' << r.eps[e].seconds << ',' << reason_name(r.eps[e].reason)
                << '\n';
}